// otherwise be drawn exactly on top of each other. Each gets a small fixed offset, and a
// parking slot on the pad while charging. Cosmetic only: under a quarter of a tile in flight.
const SEPARATION = 0.2;
const PAD_SLOT_RADIUS = 0.82;

export class DroneLayer {
  readonly group = new Group();
  /** Interpolated world-space position of each drone. Links and overlays read these. */
  readonly pos: Vector3[] = [];
  /** Screen position (CSS px) of each drone from the last frame, for picking. */
  readonly screenX: Float32Array;
  readonly screenY: Float32Array;

  private readonly bodies: InstancedMesh;
  private readonly noses: InstancedMesh;
  private readonly arms: InstancedMesh;
  private readonly rotors: InstancedMesh;
  private readonly tanks: InstancedMesh;
  private readonly labels: HTMLElement[] = [];
  private readonly bars: { w: HTMLElement; b: HTMLElement; d: HTMLElement }[] = [];
  private readonly shown: Int16Array; // last bar values written to the DOM (percent), per drone x 3

  private readonly prevX: Float32Array;
  private readonly prevY: Float32Array;
  private readonly curX: Float32Array;
  private readonly curY: Float32Array;
  private readonly heading: Float32Array;
  private readonly dock: Float32Array; // 0 = flying, 1 = parked on the pad
  private readonly lastDropped: Int32Array;
  private readonly deadAt: Float64Array;
  private readonly fallFrom: Float32Array;
  private readonly nextPuff: Float64Array;
  private readonly lastState: string[] = [];
  private readonly n: number;

  private readonly m = new Matrix4();
  private readonly local = new Matrix4();
  private readonly out = new Matrix4();
  private readonly q = new Quaternion();
  private readonly e = new Euler(0, 0, 0, "YXZ");
  private readonly s = new Vector3(SCALE, SCALE, SCALE);
  private readonly p = new Vector3();
  private readonly colour = new Color();
  private readonly armLocal = [new Matrix4().makeRotationY(Math.PI / 4), new Matrix4().makeRotationY(-Math.PI / 4)];
  private readonly screen = { x: 0, y: 0 };

  constructor(
    private world: World,
    private terrain: TerrainLayer,
    private particles: ParticleLayer,
    private labelLayer: HTMLElement,
    private padTopY: number,
  ) {
    const n = (this.n = world.drones.length);
    const cap = Math.max(1, n);
    const lambert = () => new MeshLambertMaterial({ flatShading: true });
    this.bodies = new InstancedMesh(new BoxGeometry(0.36, 0.13, 0.36), lambert(), cap);
    this.noses = new InstancedMesh(new BoxGeometry(0.16, 0.09, 0.12).translate(0, 0.01, 0.22), lambert(), cap);
    this.arms = new InstancedMesh(new BoxGeometry(0.98, 0.045, 0.07), lambert(), cap * 2);
    this.rotors = new InstancedMesh(new BoxGeometry(0.42, 0.016, 0.06), lambert(), cap * 4);
    this.tanks = new InstancedMesh(new BoxGeometry(0.2, 0.12, 0.2).translate(0, -0.06, 0), lambert(), cap);
    for (const [mesh, per] of [[this.bodies, 1], [this.noses, 1], [this.arms, 2], [this.rotors, 4], [this.tanks, 1]] as const) {
      mesh.count = n * per;
      mesh.castShadow = true;
      mesh.frustumCulled = false;
      this.group.add(mesh);
    }

    this.screenX = new Float32Array(n);
    this.screenY = new Float32Array(n);
    this.prevX = new Float32Array(n);
    this.prevY = new Float32Array(n);
    this.curX = new Float32Array(n);
    this.curY = new Float32Array(n);
    this.heading = new Float32Array(n);
    this.dock = new Float32Array(n);
    this.lastDropped = new Int32Array(n);
    this.deadAt = new Float64Array(n).fill(-1);
    this.fallFrom = new Float32Array(n);
    this.nextPuff = new Float64Array(n);
    this.shown = new Int16Array(n * 3).fill(-1);

    for (const d of world.drones) {
      const k = d.id;
      this.prevX[k] = this.curX[k] = d.x;
      this.prevY[k] = this.curY[k] = d.y;
      this.lastDropped[k] = d.waterDropped;
      this.pos.push(new Vector3(d.x, this.altitude(d.x, d.y), d.y));
      this.noses.setColorAt(k, NOSE);
      this.tanks.setColorAt(k, TANK);
      for (let a = 0; a < 2; a++) this.arms.setColorAt(k * 2 + a, ARM);
      for (let r = 0; r < 4; r++) this.rotors.setColorAt(k * 4 + r, ROTOR);

      const el = document.createElement("div");
      el.className = "dlabel";
      el.innerHTML =
        `<span class="id">${d.id}</span>` +
        `<span class="bars"><i class="w" title="water"><b></b></i><i class="b" title="battery"><b></b></i><i class="d" title="damage"><b></b></i></span>`;
      labelLayer.appendChild(el);
      this.labels.push(el);
      this.bars.push({
        w: el.querySelector(".w b") as HTMLElement,
        b: el.querySelector(".b b") as HTMLElement,
        d: el.querySelector(".d b") as HTMLElement,
      });
      this.lastState.push("");
    }
  }

  /** The sim's flying altitude at a fractional position, in world units. */
  private altitude(x: number, y: number) {
    return (terrainHeightAt(this.world.terrain, x, y) + this.world.cfg.droneAltitude) * V_SCALE;
  }

  /**
   * Call once after every world.step(): snapshots positions for interpolation and
   * turns state changes into effects (water drops, steam, crashes).
   * @param fireBefore the true fire array as it was before this tick
   */
  onTick(time: number, fireBefore: Uint8Array) {
    const world = this.world;
    const w = world.terrain.w;
    const h = world.terrain.h;
    for (const d of world.drones) {
      const k = d.id;
      this.prevX[k] = this.curX[k];
      this.prevY[k] = this.curY[k];
      this.curX[k] = d.x;
      this.curY[k] = d.y;

      if (d.waterDropped > this.lastDropped[k]) {
        this.lastDropped[k] = d.waterDropped;
        const tx = Math.max(0, Math.min(w - 1, Math.round(d.x)));
        const ty = Math.max(0, Math.min(h - 1, Math.round(d.y)));
        const tile = ty * w + tx;
        const ground = this.terrain.topY[tile];
        this.particles.waterDrop(d.x, this.altitude(d.x, d.y), d.y, ground, world.tick * 31 + k);
        if (fireBefore[tile] === Fire.Burning) this.particles.steam(tx, ground, ty, world.tick * 17 + k);
      }

      if (!d.alive && this.deadAt[k] < 0) {
        this.deadAt[k] = time;
        this.fallFrom[k] = this.pos[k].y;
        this.prevX[k] = this.curX[k]; // no more interpolation: it falls where it died
        this.prevY[k] = this.curY[k];
        this.particles.sparks(this.pos[k].x, this.pos[k].y, this.pos[k].z, world.tick * 13 + k);
      }
    }
  }

  /**
   * Per animation frame.
   * @param alpha 0..1 progress from the previous tick to the current one
   */
  update(alpha: number, time: number, dt: number, cam: IsoCamera, viewW: number, viewH: number, selected: number | null) {
    const world = this.world;
    const cfg = world.cfg;
    const n = this.n;
    const ease = 1 - Math.exp(-dt * 9);

    for (const d of world.drones) {
      const k = d.id;
      const sx = this.prevX[k] + (this.curX[k] - this.prevX[k]) * alpha;
      const sy = this.prevY[k] + (this.curY[k] - this.prevY[k]) * alpha;
      const dead = this.deadAt[k] >= 0;

      // Park on the pad while charging.
      const wantDock = d.state === "charging" ? 1 : 0;
      this.dock[k] += (wantDock - this.dock[k]) * (1 - Math.exp(-dt * 4));
      const dock = this.dock[k];
      const ringA = (k / Math.max(1, n)) * Math.PI * 2;
      const goldA = k * 2.399963;
      const offR = SEPARATION * (1 - dock) + PAD_SLOT_RADIUS * dock;
      const offA = goldA * (1 - dock) + ringA * dock;
      const x = sx + Math.cos(offA) * offR;
      const z = sy + Math.sin(offA) * offR;

      let y = this.altitude(sx, sy);
      y += (this.padTopY + 0.1 * SCALE - y) * dock;
      let pitch = 0;
      let roll = 0;

      if (dead) {
        const t = time - this.deadAt[k];
        const ground = this.terrain.topAt(x, z) + 0.08 * SCALE;
        y = this.fallFrom[k] - 2.6 * t * t;
        if (y <= ground) {
          y = ground;
          pitch = -0.32;
          roll = 0.5;
          if (time >= this.nextPuff[k]) {
            this.particles.wreckSmoke(x, y, z, Math.floor(time * 50) + k * 977); // a smoking wreck
            this.nextPuff[k] = time + 0.34;
          }
        } else {
          pitch = t * 7;
          roll = t * 5;
        }
      } else {
        const vx = this.curX[k] - this.prevX[k];
        const vy = this.curY[k] - this.prevY[k];
        const speed = Math.hypot(vx, vy);
        if (speed > 1e-3) {
          const want = Math.atan2(vx, vy); // local +Z is the nose
          let dh = want - this.heading[k];
          dh = Math.atan2(Math.sin(dh), Math.cos(dh));
          this.heading[k] += dh * ease;
        }
        pitch = Math.min(0.3, (speed / cfg.droneSpeed) * 0.24) * (1 - dock); // lean into the flight
        y += 0.03 * Math.sin(time * 3.1 + k * 1.7) * (1 - dock);
      }

      this.pos[k].set(x, y, z);
      this.e.set(pitch, this.heading[k], roll);
      this.q.setFromEuler(this.e);
      this.m.compose(this.pos[k], this.q, this.s);

      this.bodies.setMatrixAt(k, this.m);
      this.noses.setMatrixAt(k, this.m);
      this.colour.set(STATE_COLOUR[d.state] ?? "#ffffff");
      this.bodies.setColorAt(k, dead ? WRECK : this.colour);

      for (let a = 0; a < 2; a++) this.arms.setMatrixAt(k * 2 + a, this.out.multiplyMatrices(this.m, this.armLocal[a]));

      // Rotors: full speed in flight, idling on the pad, stopped when wrecked.
      const spin = dead ? 0.4 + k : time * (5 + 25 * (1 - dock)) + k;
      for (let r = 0; r < 4; r++) {
        const ex = r < 2 ? ARM_END : -ARM_END;
        const ez = r % 2 === 0 ? ARM_END : -ARM_END;
        this.local.makeRotationY(spin * (r % 2 === 0 ? 1 : -1) + r).setPosition(ex, ROTOR_Y, ez);
        this.rotors.setMatrixAt(k * 4 + r, this.out.multiplyMatrices(this.m, this.local));
      }

      // Water tank under the body: you can see the load shrink with each drop.
      const load = Math.max(0, d.water / cfg.waterCapacity);
      this.local.makeScale(1, Math.max(0.001, load), 1).setPosition(0, -0.065, 0);
      this.tanks.setMatrixAt(k, this.out.multiplyMatrices(this.m, this.local));

      // Label and bars.
      cam.project(this.p.set(x, y, z), viewW, viewH, this.screen);
      this.screenX[k] = this.screen.x;
      this.screenY[k] = this.screen.y;
      const el = this.labels[k];
      el.style.transform = `translate(${this.screen.x.toFixed(1)}px, ${(this.screen.y - 18).toFixed(1)}px) translate(-50%, -100%)`;
      const state = (dead ? "dead" : d.state) + (k === selected ? " sel" : "");
      if (state !== this.lastState[k]) {
        this.lastState[k] = state;
        el.className = "dlabel " + state;
      }
      this.setBar(k, 0, this.bars[k].w, load);
      this.setBar(k, 1, this.bars[k].b, d.battery);
      this.setBar(k, 2, this.bars[k].d, d.damage);
    }

    for (const mesh of [this.bodies, this.noses, this.arms, this.rotors, this.tanks]) {
      mesh.instanceMatrix.needsUpdate = true;
    }
    if (this.bodies.instanceColor) this.bodies.instanceColor.needsUpdate = true;
  }

  private setBar(k: number, slot: number, el: HTMLElement, value: number) {
    const pct = Math.round(Math.max(0, Math.min(1, value)) * 50) * 2; // 2% steps: few DOM writes
    if (this.shown[k * 3 + slot] === pct) return;
    this.shown[k * 3 + slot] = pct;
    el.style.transform = `scaleX(${pct / 100})`;
  }

  dispose() {
    for (const el of this.labels) el.remove();
  }
}

input.content:
// Overlays: everything drawn on top of the world to explain what the swarm is doing.
//   - comms links: glowing beams between nodes, at the altitudes the sim uses for line of sight
//   - blackout zones: translucent purple domes
//   - for the selected drone: sensor ring, target line, guesses about lost teammates
//   - the tile under the cursor
import {
  AdditiveBlending,
  BoxGeometry,
  Color,
  DoubleSide,
  EdgesGeometry,
  Group,
  InstancedMesh,
  LatheGeometry,
  LineBasicMaterial,
  LineSegments,
  Mesh,
  MeshBasicMaterial,
  RingGeometry,
  Vector2,
  Vector3,
} from "three";
import { BASE_ID } from "../../sim/comms";
import { World } from "../../sim/world";
import { STATE_COLOUR, TEAM_COLOURS, ViewOptions } from "../renderer";
import { TerrainLayer } from "./terrain";
import { V_SCALE, hideInstance, rgb, setBeam, setInstance, uploadUsed } from "./util";

const LINK = rgb(0x8ff3ff);
const MAX_LINKS = 1024;
const MAX_DASHES = 3000;
const RING_DOTS = 72;
const BLACKOUT = 0xc77dff;

export interface HoverState {
  tile: number | null;
  /** Radius (tiles) of a preview circle around the hovered tile, 0 for none (blackout tool). */
  radius: number;
}

export class OverlayLayer {
  readonly group = new Group();
  private readonly beams: InstancedMesh;
  private readonly glow: InstancedMesh;
  private readonly dashes: InstancedMesh;
  private readonly dots: InstancedMesh;
  private readonly domes = new Group();
  private domesBuiltFor: unknown = null;
  private domeCount = 0;
  private readonly marker: Mesh;
  private readonly selRing: Mesh;
  private readonly hover: Mesh;
  private readonly a = new Vector3();
  private readonly b = new Vector3();
  private readonly c = new Vector3();
  private readonly colour = new Color();
  private dashCount = 0;
  private dotCount = 0;

  constructor(private world: World, private terrain: TerrainLayer) {
    const box = new BoxGeometry(1, 1, 1);
    const linkMat = (opacity: number) =>
      new MeshBasicMaterial({
        color: LINK,
        transparent: true,
        opacity,
        blending: AdditiveBlending,
        depthWrite: false,
        toneMapped: false,
      });
    this.beams = new InstancedMesh(box, linkMat(0.95), MAX_LINKS);
    this.glow = new InstancedMesh(box, linkMat(0.2), MAX_LINKS);
    this.dashes = new InstancedMesh(box, new MeshBasicMaterial({ toneMapped: false }), MAX_DASHES);
    const dotCapacity = RING_DOTS * 2 + world.drones.length * world.cfg.trackerParticles + 8;
    this.dots = new InstancedMesh(box, new MeshBasicMaterial({ toneMapped: false, transparent: true, opacity: 0.85 }), dotCapacity);
    for (const m of [this.beams, this.glow, this.dashes, this.dots]) {
      m.count = 0;
      m.frustumCulled = false;
      m.renderOrder = 8;
    }
    this.dashes.setColorAt(0, this.colour.set(0xffffff));
    this.dots.setColorAt(0, this.colour);

    const flatRing = (inner: number, outer: number, colour: number, opacity: number) =>
      new Mesh(
        new RingGeometry(inner, outer, 24).rotateX(-Math.PI / 2),
        new MeshBasicMaterial({ color: colour, transparent: true, opacity, side: DoubleSide, depthWrite: false, toneMapped: false }),
      );
    this.marker = flatRing(0.34, 0.5, 0xffffff, 0.9);
    this.selRing = flatRing(0.5, 0.62, 0xffffff, 0.95);
    this.hover = new Mesh(
      new BoxGeometry(1.02, 0.06, 1.02),
      new MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.35, depthWrite: false, toneMapped: false }),
    );
    for (const m of [this.marker, this.selRing, this.hover]) {
      m.visible = false;
      m.renderOrder = 9;
    }
    this.group.add(this.domes, this.glow, this.beams, this.dashes, this.dots, this.marker, this.selRing, this.hover);
  }

  /**
   * @param nodePos   world position of a comms node (drone id, or BASE_ID)
   * @param pxToWorld world units per screen pixel, so line widths stay constant on screen
   */
  update(
    view: ViewOptions,
    hover: HoverState,
    time: number,
    pxToWorld: number,
    nodePos: (id: number) => Vector3 | null,
  ) {
    const world = this.world;
    this.dashCount = 0;
    this.dotCount = 0;

    // ------------------------------------------------------------ usable links
    let n = 0;
    if (view.showLinks) {
      const core = 2.2 * pxToWorld;
      const halo = 7 * pxToWorld;
      for (const [ia, ib] of world.network.links) {
        const pa = nodePos(ia);
        const pb = nodePos(ib);
        if (!pa || !pb || n >= MAX_LINKS) continue;
        setBeam(this.beams, n, pa, pb, core);
        setBeam(this.glow, n, pa, pb, halo);
        n++;
      }
    }
    this.beams.count = this.glow.count = n;
    uploadUsed(this.beams.instanceMatrix, n);
    uploadUsed(this.glow.instanceMatrix, n);

    // ------------------------------------------------------------ blackout zones
    this.syncDomes();
    const breathe = 0.16 + 0.04 * Math.sin(time * 1.6);
    for (const dome of this.domes.children) ((dome as Mesh).material as MeshBasicMaterial).opacity = breathe;

    // ------------------------------------------------------------ selected drone
    const sel = view.selected !== null ? world.drones[view.selected] : null;
    const selPos = sel ? nodePos(sel.id) : null;
    this.selRing.visible = !!(sel && selPos);
    this.marker.visible = false;
    if (sel && selPos) {
      this.selRing.position.copy(selPos);
      this.selRing.position.y -= 0.12;
      const pulse = 1 + 0.08 * Math.sin(time * 5);
      this.selRing.scale.set(pulse, 1, pulse);

      if (sel.alive) {
        // A drop line to the ground: in an isometric view height is otherwise ambiguous.
        this.a.copy(selPos);
        this.b.set(selPos.x, this.terrain.topAt(selPos.x, selPos.z), selPos.z);
        this.addDashes(this.a, this.b, 0xffffff, 1.4 * pxToWorld, 0.12, 0.1, 0);

        if (view.showSensors) this.addRing(sel.x, sel.y, this.sensorRadius(sel.x, sel.y), 0xffffff, time * 0.15);

        // Where it is heading, in the colour of what it is doing.
        const moving = sel.state === "toFire" || sel.state === "toWater" || sel.state === "scouting" || sel.state === "toBase";
        if (moving) {
          const tx = sel.state === "toBase" ? world.base.x : sel.targetX;
          const ty = sel.state === "toBase" ? world.base.y : sel.targetY;
          const hex = this.colour.set(STATE_COLOUR[sel.state] ?? "#ffffff").getHex();
          this.b.set(tx, this.terrain.topAt(tx, ty) + 0.12, ty);
          this.addDashes(selPos, this.b, hex, 2 * pxToWorld, 0.4, 0.3, time * 1.6);
          this.marker.visible = true;
          this.marker.position.copy(this.b);
          (this.marker.material as MeshBasicMaterial).color.set(hex);
          const s = 1 + 0.25 * Math.sin(time * 6);
          this.marker.scale.set(s, 1, s);
        }

        // Its guesses about teammates it can no longer hear: one voxel per particle.
        if (view.showClouds) {
          const alt = world.cfg.droneAltitude * V_SCALE;
          for (const [id, tr] of sel.trackers) {
            this.colour.set(TEAM_COLOURS[id % TEAM_COLOURS.length]);
            for (let k = 0; k < tr.n; k++) {
              if (this.dotCount >= this.dots.instanceMatrix.count) break;
              const x = tr.xs[k];
              const z = tr.ys[k];
              setInstance(this.dots, this.dotCount, x, this.terrain.topAt(x, z) + alt, z, 0.17, 0.17, 0.17);
              this.dots.setColorAt(this.dotCount++, this.colour);
            }
          }
        }
      }
    }

    // ------------------------------------------------------------ hover
    this.hover.visible = hover.tile !== null;
    if (hover.tile !== null) {
      const w = world.terrain.w;
      const hx = hover.tile % w;
      const hy = (hover.tile - hx) / w;
      this.hover.position.set(hx, this.terrain.topY[hover.tile] + 0.04, hy);
      if (hover.radius > 0) this.addRing(hx, hy, hover.radius, BLACKOUT, 0);
    }

    this.dashes.count = this.dashCount;
    uploadUsed(this.dashes.instanceMatrix, this.dashCount);
    uploadUsed(this.dashes.instanceColor, this.dashCount);
    this.dots.count = this.dotCount;
    uploadUsed(this.dots.instanceMatrix, this.dotCount);
    uploadUsed(this.dots.instanceColor, this.dotCount);
  }

  /** The radius the selected drone can actually see right now (thick smoke shrinks it, as in Drone.sense). */
  private sensorRadius(x: number, y: number): number {
    const cfg = this.world.cfg;
    let r = cfg.sensorRadius;
    if (cfg.smokeBlocksSensing) r = r / (1 + this.world.env.smokeAt(x, y) / cfg.thickSmoke);
    return Math.max(1.5, r);
  }

  /** A circle of voxels draped over the terrain. */
  private addRing(cx: number, cy: number, radius: number, hex: number, spin: number) {
    this.colour.set(hex);
    for (let k = 0; k < RING_DOTS; k++) {
      if (this.dotCount >= this.dots.instanceMatrix.count) return;
      const ang = (k / RING_DOTS) * Math.PI * 2 + spin;
      const x = cx + Math.cos(ang) * radius;
      const z = cy + Math.sin(ang) * radius;
      const inside = x >= -0.5 && z >= -0.5 && x <= this.terrain.w - 0.5 && z <= this.terrain.h - 0.5;
      if (!inside) continue;
      setInstance(this.dots, this.dotCount, x, this.terrain.topAt(x, z) + 0.1, z, 0.13, 0.13, 0.13);
      this.dots.setColorAt(this.dotCount++, this.colour);
    }
  }

  /**
   * A dashed line from `from` to `to`. `offset` slides the dashes along the line
   * (animate it for a marching effect).
   */
  addDashes(from: Vector3, to: Vector3, hex: number, thickness: number, dash: number, gap: number, offset: number) {
    const len = from.distanceTo(to);
    if (len < 1e-4) return;
    const period = dash + gap;
    this.colour.set(hex);
    let s = -(((offset % period) + period) % period);
    while (s < len && this.dashCount < MAX_DASHES) {
      const s0 = Math.max(0, s);
      const s1 = Math.min(len, s + dash);
      if (s1 > s0) {
        this.c.copy(from).lerp(to, s0 / len);
        const end = this.a === from || this.a === to ? new Vector3() : this.a;
        end.copy(from).lerp(to, s1 / len);
        setBeam(this.dashes, this.dashCount, this.c, end, thickness);
        this.dashes.setColorAt(this.dashCount++, this.colour);
      }
      s += period;
    }
  }

  /** Rebuild the dome meshes when the sim's blackout list changes (judges add or clear them). */
  private syncDomes() {
    const list = this.world.blackouts;
    if (this.domesBuiltFor === list && this.domeCount === list.length) return;
    this.domesBuiltFor = list;
    this.domeCount = list.length;
    for (const child of [...this.domes.children]) {
      this.domes.remove(child);
      (child as Mesh).geometry.dispose();
      ((child as Mesh).material as MeshBasicMaterial).dispose();
      for (const edge of child.children) {
        (edge as LineSegments).geometry.dispose();
        ((edge as LineSegments).material as LineBasicMaterial).dispose();
      }
    }
    const { w, h } = this.world.terrain;
    for (const zone of list) {
      // The sim's blackout is a vertical cylinder; a straight-walled dome keeps the visual
