input.content:
:root {
  --bg: #14161a;
  --panel: #1d2026;
  --line: #2c313a;
  --text: #e8e6e3;
  --dim: #9aa0a6;
  --accent: #ff9f1c;
  --bad: #ff595e;
  --good: #80ed99;
  --glass: rgba(20, 22, 26, 0.82);
}
* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 14px/1.4 system-ui, sans-serif;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(320px, 400px);
  grid-template-rows: auto minmax(0, 1fr);
  height: 100vh;
  overflow: hidden;
}

header {
  grid-column: 1 / -1;
  padding: 8px 16px;
  border-bottom: 1px solid var(--line);
  display: flex;
  align-items: baseline;
  gap: 12px;
}
header h1 { margin: 0; font-size: 20px; }
header h1 span { color: var(--accent); }
header p { margin: 0; color: var(--dim); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
header .spacer { flex: 1; }
.perf { color: var(--dim); font-size: 12px; font-variant-numeric: tabular-nums; white-space: nowrap; }

/* ------------------------------------------------------------------ stage */
#stage { position: relative; overflow: hidden; background: #18222e; min-width: 0; min-height: 0; }
.iso-canvas { display: block; width: 100%; height: 100%; cursor: grab; touch-action: none; outline: none; }
.iso-canvas.dragging { cursor: grabbing; }
#stage:not([data-tool="select"]) .iso-canvas:not(.dragging) { cursor: crosshair; }
.iso-labels { position: absolute; inset: 0; pointer-events: none; overflow: hidden; }

.dlabel {
  position: absolute; left: 0; top: 0;
  display: flex; flex-direction: column; align-items: center; gap: 2px;
  will-change: transform;
  font: 700 11px/1 system-ui, sans-serif;
  color: #fff;
}
.dlabel .id {
  min-width: 17px; text-align: center;
  background: rgba(12, 14, 18, 0.78);
  border: 1.5px solid #e0e0e0;
  border-radius: 9px;
  padding: 2px 4px;
}
.dlabel.toFire .id { border-color: #ff9f1c; }
.dlabel.toWater .id, .dlabel.refilling .id { border-color: #4cc9f0; }
.dlabel.toBase .id, .dlabel.charging .id { border-color: #b388ff; }
.dlabel.scouting .id { border-color: #80ed99; }
.dlabel.sel .id { background: #fff; color: #111; box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.35); }
.dlabel .bars { display: flex; flex-direction: column; gap: 1px; width: 26px; }
.dlabel .bars i { display: block; height: 3px; background: rgba(0, 0, 0, 0.62); border-radius: 1px; overflow: hidden; }
.dlabel .bars b { display: block; height: 100%; transform-origin: left center; }
.dlabel .w b { background: #4cc9f0; }
.dlabel .b b { background: #80ed99; }
.dlabel .d b { background: #ff595e; }
.dlabel.dead { opacity: 0.6; }
.dlabel.dead .id { border-color: #666; color: #aaa; text-decoration: line-through; }
.dlabel.dead .bars { display: none; }

.hud { position: absolute; display: flex; gap: 8px; pointer-events: none; }
.hud > * { pointer-events: auto; }
.hud.top-left { top: 12px; left: 12px; flex-direction: column; align-items: flex-start; }
.hud.top-right { top: 12px; right: 12px; flex-direction: column; align-items: flex-end; }
.hud.bottom-left { bottom: 12px; left: 12px; }
.hud.bottom-centre { bottom: 12px; left: 50%; transform: translateX(-50%); }

.badge {
  background: var(--glass); border: 1px solid var(--accent); color: var(--text);
  border-radius: 999px; padding: 5px 12px; font-weight: 600; backdrop-filter: blur(4px);
}
.badge small { color: var(--dim); font-weight: 400; }

.banner {
  position: absolute; top: 12px; left: 50%; transform: translateX(-50%);
  background: rgba(120, 18, 22, 0.92); border: 1px solid var(--bad); color: #fff;
  border-radius: 8px; padding: 7px 16px; font-weight: 700; letter-spacing: 0.04em;
  box-shadow: 0 6px 24px rgba(0, 0, 0, 0.45); white-space: nowrap;
  animation: banner-in 0.35s ease-out;
}
.banner small { font-weight: 400; opacity: 0.85; letter-spacing: 0; margin-left: 8px; }
@keyframes banner-in { from { transform: translate(-50%, -140%); } to { transform: translate(-50%, 0); } }

.compass {
  background: var(--glass); border: 1px solid var(--line); border-radius: 10px;
  padding: 4px 6px 6px; text-align: center; backdrop-filter: blur(4px);
}
.compass-ring { fill: rgba(255, 255, 255, 0.04); stroke: #3a404a; stroke-width: 2; }
.compass-shaft { stroke: var(--accent); stroke-width: 7; stroke-linecap: round; }
.compass-head { fill: var(--accent); }
.compass-label { font-size: 11px; color: var(--dim); letter-spacing: 0.08em; }
.compass-label b { color: var(--text); font-variant-numeric: tabular-nums; }
.cam-buttons { display: flex; gap: 4px; }
.cam-buttons button { padding: 4px 8px; font-size: 12px; background: var(--glass); }

.minimap {
  position: relative; background: var(--glass); border: 1px solid var(--line);
  border-radius: 8px; padding: 4px; line-height: 0; backdrop-filter: blur(4px);
}
.minimap canvas { width: 192px; height: 192px; border-radius: 4px; cursor: pointer; image-rendering: pixelated; }
.minimap-mode {
  position: absolute; left: 8px; top: 8px; padding: 2px 7px; font-size: 11px; line-height: 1.4;
  background: rgba(12, 14, 18, 0.8);
}

.transport {
  align-items: center; background: var(--glass); border: 1px solid var(--line);
  border-radius: 10px; padding: 6px 10px; backdrop-filter: blur(4px); white-space: nowrap;
}
.transport label { color: var(--dim); }
.transport input[type="range"] { width: 150px; flex: none; }
.transport b { font-variant-numeric: tabular-nums; min-width: 26px; text-align: right; display: inline-block; }
.transport .unit, .transport .tick { color: var(--dim); font-size: 12px; }
.transport .tick { margin-left: 6px; }
.transport .tick b { color: var(--text); min-width: 34px; }

.endcard {
  position: absolute; left: 50%; top: 50%; transform: translate(-50%, -50%);
  width: min(430px, calc(100% - 32px));
  background: rgba(24, 27, 33, 0.95); border: 1px solid var(--line); border-radius: 14px;
  padding: 18px 20px; box-shadow: 0 18px 60px rgba(0, 0, 0, 0.6); backdrop-filter: blur(6px);
}
.endcard h2 { margin: 0 0 2px; font-size: 22px; text-transform: none; letter-spacing: 0; color: var(--text); }
.endcard p { margin: 0 0 12px; color: var(--dim); }
.endcard .stats { margin-bottom: 14px; }
.endcard.saved { border-color: var(--good); }
.endcard.lost { border-color: var(--bad); }

/* ------------------------------------------------------------------ sidebar */
aside {
  overflow-y: auto; padding: 12px; display: flex; flex-direction: column; gap: 10px;
  border-left: 1px solid var(--line); min-height: 0;
}
section { background: var(--panel); border: 1px solid var(--line); border-radius: 8px; padding: 10px 12px; }
section h2, .endcard h3 { margin: 0 0 8px; font-size: 12px; text-transform: uppercase; letter-spacing: 0.08em; color: var(--dim); }
.row { display: flex; align-items: center; gap: 8px; margin: 5px 0; flex-wrap: wrap; }
.row > label:not(.check) { min-width: 92px; color: var(--dim); }
label.check { color: var(--text); display: inline-flex; align-items: center; gap: 4px; }
button, select, input[type="number"], input[type="text"] {
  background: #2a2f37; color: var(--text); border: 1px solid #3a404a; border-radius: 5px; padding: 5px 9px; font: inherit;
}
button:hover { border-color: var(--accent); cursor: pointer; }
button:disabled { opacity: 0.5; cursor: default; border-color: #3a404a; }
button.on { background: var(--accent); color: #111; border-color: var(--accent); }
input[type="range"] { flex: 1; accent-color: var(--accent); }
.stats { display: grid; grid-template-columns: 1fr 1fr; gap: 4px 12px; }
.stats b { font-variant-numeric: tabular-nums; }
.bad { color: var(--bad); }
.good { color: var(--good); }
table { width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums; }
td, th { text-align: left; padding: 2px 4px; border-bottom: 1px solid var(--line); }
th { color: var(--dim); font-weight: normal; }
.legend span { display: inline-flex; align-items: center; gap: 4px; margin-right: 10px; color: var(--dim); font-size: 12px; }
.legend i { width: 10px; height: 10px; border-radius: 50%; display: inline-block; }
#chart { width: 100%; height: 70px; }
.hint { color: var(--dim); font-size: 12px; margin: 4px 0 0; }
kbd {
  background: #2a2f37; border: 1px solid #3a404a; border-bottom-width: 2px; border-radius: 4px;
  padding: 0 4px; font: 11px ui-monospace, monospace; color: var(--text);
}
[hidden] { display: none !important; }

@media (max-width: 900px) {
  body { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto 62vh auto; height: auto; overflow: auto; }
  aside { border-left: none; border-top: 1px solid var(--line); overflow: visible; }
  header p { display: none; }
  .minimap canvas { width: 128px; height: 128px; }
}

