        hot.setPlaying(false);
        const badge = document.getElementById("viewBadge").innerText;
        while (!world.finished) hot.stepOnce();
        const m2 = JSON.stringify(world.metrics());
        return { badgeAtStart: badge, identicalMetrics: m2 === window.__m1, identicalLog: JSON.stringify(world.judgeLog) === window.__log1, m2 };
      });
    }, wait: 1500 },
  { name: "newseed", run: async (page) => { await page.click("#endNewSeed"); await page.waitForTimeout(600); return page.evaluate(() => ({ seed: world.cfg.seed, mode: world.cfg.mode, tick: world.tick, cardHidden: document.getElementById("endcard").hidden, bannerHidden: document.getElementById("banner").hidden })); }, wait: 800 },
];
