    if (ok) c = y * 64 + x;
  }
  const cluster = [c, c + 1, c - 1, c + 64, c - 64, c + 65, c - 65, c + 63, c - 63].slice(0, tiles);
  w.setWind(0.7, wind);
  for (const i of cluster) w.env.ignite(i, 3);
  let peak = 0;
  for (let k = 0; k < 69; k++) {
