// 1. Smoke from N clustered tiles held at maximum severity, by wind speed.
function peakSmoke(model: "legacy" | "massed", tiles: number, wind: number): number {
  const w = new World({ seed: 3, ignitions: 0, preburnTicks: 0, droneCount: 0, spreadBase: 0, embers: false, windDrift: false, smokeModel: model, regrowth: false });
  const t = w.terrain;
  // find a forest tile whose 3x3 block is all forest
  let c = -1;
  for (let y = 5; y < 59 && c < 0; y++) for (let x = 5; x < 59 && c < 0; x++) {
    let ok = true;
    for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) if (t.type[(y + dy) * 64 + x + dx] !== 1) ok = false;
    if (ok) c = y * 64 + x;
  }
  const cluster = [c, c + 1, c - 1, c + 64, c - 64, c + 65, c - 65, c + 63, c - 63].slice(0, tiles);
  w.setWind(0.7, wind);
  for (const i of cluster) w.env.ignite(i, 3);
  let peak = 0;
  for (let k = 0; k < 69; k++) {
    for (const i of cluster) if (w.env.fire[i] === Fire.Burning) w.env.severity[i] = 3; // worst case: pinned at max severity
    w.env.step(k);
    for (let i = 0; i < w.env.smoke.length; i++) peak = Math.max(peak, w.env.smoke[i]);
  }
  return peak;
}
